const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, param, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');
const winston = require('winston');

const app = express();

// =============================================================================
// SECURITY CONFIGURATION
// =============================================================================

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Stricter rate limiting for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many login attempts, please try again later'
});
app.use('/api/auth/', authLimiter);

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// =============================================================================
// LOGGING
// =============================================================================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'security.log', level: 'warn' })
  ]
});

// Request logging middleware
app.use((req, res, next) => {
  const startTime = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - startTime;
    logger.info({
      method: req.method,
      url: req.url,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent')
    });
  });

  next();
});

// =============================================================================
// AUTHENTICATION & AUTHORIZATION
// =============================================================================

// JWT Authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn({ securityEvent: 'missing_token', ip: req.ip, url: req.url });
    return res.status(401).json({ error: 'Access token required' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    logger.warn({ 
      securityEvent: 'invalid_token', 
      ip: req.ip, 
      url: req.url,
      error: error.message 
    });
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
};

// Role-based authorization middleware
const requireRole = (...roles) => {
  return (req, res, next) => {
    if (!req.user || !roles.includes(req.user.role)) {
      logger.warn({ 
        securityEvent: 'unauthorized_access', 
        ip: req.ip, 
        userId: req.user?.id,
        requiredRoles: roles 
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

// =============================================================================
// INPUT VALIDATION HELPERS
// =============================================================================

const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn({ 
      validationErrors: errors.array(),
      ip: req.ip,
      url: req.url 
    });
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array() 
    });
  }
  next();
};

// =============================================================================
// ROUTES
// =============================================================================

// Health check - public, no auth required
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.APP_VERSION || '1.0.0'
  });
});

// Authentication endpoints
app.post('/api/auth/login', [
  body('email').isEmail().normalizeEmail().toLowerCase(),
  body('password').isLength({ min: 8, max: 128 })
], validateRequest, async (req, res) => {
  const { email, password } = req.body;

  try {
    // In production, this would query a database
    // const user = await findUserByEmail(email);

    // Simulated user lookup (replace with actual DB query)
    const user = { id: 1, email, passwordHash: await bcrypt.hash('demoPassword123!', 10), role: 'user' };

    // Verify password (timing-safe comparison)
    const isValid = await bcrypt.compare(password, user.passwordHash);

    if (!isValid) {
      logger.warn({ 
        securityEvent: 'failed_login', 
        email, 
        ip: req.ip 
      });
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // Generate JWT with short expiration
    const token = jwt.sign(
      { id: user.id, email: user.email, role: user.role },
      process.env.JWT_SECRET || 'your-secret-key-change-in-production',
      { expiresIn: '15m', issuer: 'your-app-name' }
    );

    // Generate refresh token (in production, store in database with expiry)
    const refreshToken = jwt.sign(
      { id: user.id, type: 'refresh' },
      process.env.JWT_REFRESH_SECRET || 'your-refresh-secret',
      { expiresIn: '7d' }
    );

    logger.info({ 
      securityEvent: 'successful_login', 
      userId: user.id, 
      ip: req.ip 
    });

    res.json({ 
      token,
      refreshToken,
      expiresIn: 900 // 15 minutes in seconds
    });
  } catch (error) {
    logger.error({ 
      error: error.message, 
      stack: error.stack,
      endpoint: '/api/auth/login'
    });
    res.status(500).json({ error: 'Authentication failed' });
  }
});

// Protected user endpoints
app.get('/api/users', [
  authenticateToken,
  requireRole('admin')
], async (req, res) => {
  try {
    // In production, query database with parameterized queries
    // const users = await db.query('SELECT id, name, email FROM users');

    // Data minimization: only return necessary fields
    // Remove sensitive data like passwords, tokens, etc.
    const users = [
      { id: 1, name: 'Alice' }, // Email removed for non-admin safety
      { id: 2, name: 'Bob' }
    ];

    res.json({ 
      data: users,
      count: users.length 
    });
  } catch (error) {
    logger.error({ error: error.message, endpoint: '/api/users' });
    res.status(500).json({ error: 'Failed to retrieve users' });
  }
});

// Get specific user (with parameter validation)
app.get('/api/users/:id', [
  authenticateToken,
  param('id').isInt({ min: 1 }).toInt(),
  validateRequest
], async (req, res) => {
  const userId = req.params.id;

  try {
    // Users can only see their own data unless they're admin
    if (req.user.role !== 'admin' && req.user.id !== userId) {
      logger.warn({ 
        securityEvent: 'unauthorized_user_access', 
        requesterId: req.user.id, 
        targetId: userId 
      });
      return res.status(403).json({ error: 'Access denied' });
    }

    // Simulated user lookup
    const user = { id: userId, name: 'Alice', role: 'user' };

    // Only include email if it's the user themselves
    const response = {
      id: user.id,
      name: user.name,
      role: user.role
    };

    if (req.user.id === userId) {
      response.email = 'alice@example.com';
    }

    res.json(response);
  } catch (error) {
    logger.error({ error: error.message, endpoint: `/api/users/${userId}` });
    res.status(500).json({ error: 'Failed to retrieve user' });
  }
});

// =============================================================================
// ERROR HANDLING
// =============================================================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    path: req.url 
  });
});

// Global error handler
app.use((err, req, res, next) => {
  logger.error({
    error: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't leak stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: {
      message: isDevelopment ? err.message : 'Internal server error',
      ...(isDevelopment && { stack: err.stack })
    }
  });
});

// =============================================================================
// SERVER STARTUP
// =============================================================================

const PORT = process.env.PORT || 3000;

if (require.main === module) {
  app.listen(PORT, () => {
    logger.info(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
  });
}

module.exports = app;

