// config/secrets.js
const AWS = require('aws-sdk');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ 
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.ttl = 5 * 60 * 1000; // 5 minute cache
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.ttl) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      const secret = response.SecretString 
        ? JSON.parse(response.SecretString) 
        : response.SecretBinary;

      // Cache the result
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error.message);
      throw new Error('Secret retrieval failed');
    }
  }
}

const secretsManager = new SecretsManager();

// Load configuration at startup
async function loadConfig() {
  const dbSecret = await secretsManager.getSecret('prod/app/database');
  const jwtSecret = await secretsManager.getSecret('prod/app/jwt');

  return {
    databaseUrl: dbSecret.url,
    username: dbSecret.username,
    password: dbSecret.password,
    jwtSecret: jwtSecret.value,
    stripeKey: process.env.STRIPE_SECRET_KEY // Fallback
  };
}

module.exports = { loadConfig, secretsManager };
```

