  async getSecret(secretName) {
    // Check cache first
    if (this.secretsCache.has(secretName)) {
      return this.secretsCache.get(secretName);
    }

    // In development, use environment variables
    if (this.useLocalEnv) {
      const envValue = process.env[secretName];
      if (!envValue) {
        throw new Error(`Missing environment variable: ${secretName}`);
      }
      this.secretsCache.set(secretName, envValue);
      return envValue;
    }

    // In production, fetch from AWS Secrets Manager
    try {
      const client = new SecretsManagerClient({ region: process.env.AWS_REGION });
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await client.send(command);

      const secret = response.SecretString 
        ? JSON.parse(response.SecretString) 
        : response.SecretBinary;

      this.secretsCache.set(secretName, secret);
      return secret;
    } catch (error) {
      throw new Error(`Failed to fetch secret ${secretName}: ${error.message}`);
    }
  }

  // For SSM Parameter Store
  async getParameter(parameterName, decrypt = true) {
    if (this.useLocalEnv) {
      return process.env[parameterName];
    }

    const client = new SSMClient({ region: process.env.AWS_REGION });
    const command = new GetParameterCommand({ 
      Name: parameterName, 
      WithDecryption: decrypt 
    });

    const response = await client.send(command);
    return response.Parameter.Value;
  }

  // Clear cache (useful for rotation)
  clearCache() {
    this.secretsCache.clear();
  }

  // Preload all secrets at startup
  async loadAllSecrets(secretNames) {
    const secrets = {};
    for (const name of secretNames) {
      secrets[name] = await this.getSecret(name);
    }
    return secrets;
  }
}

module.exports = new SecretManager();
```

