### Option 2: Using AWS Secrets Manager (Recommended for AWS)

```javascript
// config/secrets.js
const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTTL = 15 * 60 * 1000; // 15 minutes
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    // Fetch from Secrets Manager
    try {
      const data = await this.client.getSecretValue({ SecretId: secretName }).promise();
      let secret;

      if ('SecretString' in data) {
        secret = JSON.parse(data.SecretString);
      } else {
        secret = Buffer.from(data.SecretBinary, 'base64').toString();
      }

      // Cache the result
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      throw new Error(`Failed to fetch secret ${secretName}: ${error.message}`);
    }
  }
}

module.exports = { SecretsManager };
```

