```javascript
// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-east-1'
});

async function getSecret(secretName) {
  try {
    const command = new GetSecretValueCommand({ SecretId: secretName });
    const response = await client.send(command);

    if (response.SecretString) {
      return JSON.parse(response.SecretString);
    }

    // Handle binary secrets
    const binarySecret = Buffer.from(response.SecretBinary, 'base64');
    return binarySecret.toString('utf-8');

  } catch (err) {
    console.error(`Error retrieving secret ${secretName}:`, err.message);
    throw err;
  }
}

// Cache secrets (with TTL)
let cachedSecrets = {};
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

async function getCachedSecret(secretName) {
  const now = Date.now();

  if (cachedSecrets[secretName] && cachedSecrets[secretName].expiry > now) {
    return cachedSecrets[secretName].data;
  }

  const data = await getSecret(secretName);
  cachedSecrets[secretName] = {
    data,
    expiry: now + CACHE_TTL
  };

  return data;
}

module.exports = { getCachedSecret, getSecret };
```

**Usage in app.js:**
