// Middleware to validate content type
const enforceContentType = (types) => (req, res, next) => {
  const contentType = req.get('content-type');

  if (!contentType) {
    return res.status(415).json({ error: 'Content-Type header required' });
  }

  // Parse the content type (e.g., "application/json; charset=utf-8")
  const mimeType = contentType.split(';')[0].trim();

  if (!types.includes(mimeType)) {
    return res.status(415).json({ 
      error: `Unsupported content type: ${mimeType}. Supported: ${types.join(', ')}` 
    });
  }

  next();
};

// Usage
app.post('/users', 
  enforceContentType(['application/json']),
  (req, res) => {
    // Process JSON request
  }
);
