// config/secrets.js
const {
  SecretsManagerClient,
  GetSecretValueCommand,
} = require('@aws-sdk/client-secrets-manager');

const { parse } = require('dotenv');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
    });
    this.cache = new Map();
    this.cacheTTL = parseInt(process.env.SECRET_CACHE_TTL || '300000'); // 5 min
  }

  async getSecret(secretName, forceRefresh = false) {
    // Check cache first (unless forcing refresh)
    if (!forceRefresh && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      const cacheAge = Date.now() - cached.timestamp;
      if (cacheAge < this.cacheTTL) {
        return cached.value;
      }
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      let secretValue;
      if (response.SecretString) {
        // Handle string secrets
        secretValue = response.SecretString;

        // If it's a JSON secret, parse it
        try {
          secretValue = JSON.parse(secretValue);
        } catch {
          // Keep as string if not JSON
        }
      } else if (response.SecretBinary) {
        // Handle binary secrets (Base64 encoded)
        secretValue = Buffer.from(response.SecretBinary, 'base64').toString('utf-8');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now(),
      });

      return secretValue;
    } catch (error) {
      // Security: Don't expose secret name in errors
      console.error('Failed to retrieve secret:', error.code);
      throw new Error('Failed to retrieve configuration');
    }
  }

  async loadAllSecrets(secretConfig) {
    const secrets = {};

    for (const [key, secretName] of Object.entries(secretConfig)) {
      secrets[key] = await this.getSecret(secretName);
    }

    return secrets;
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

module.exports = {
  secretsManager,

  async getPostgresConfig() {
