}
```

**Option C: Cloud KMS for Encryption (Hybrid Approach)**
```javascript
const crypto = require('crypto');
const kms = new (require('@aws-sdk/client-kms')).KMSClient();

// Encrypt secrets during deployment
async function encryptSecret(plaintext, keyId) {
  const { EncryptCommand } = require('@aws-sdk/client-kms');

  const command = new EncryptCommand({
    KeyId: keyId,
    Plaintext: Buffer.from(plaintext),
  });

  const response = await kms.send(command);
  return response.CiphertextBlob.toString('base64');
}

// Decrypt at runtime
async function decryptSecret(ciphertext) {
  const { DecryptCommand } = require('@aws-sdk/client-kms');

  const command = new DecryptCommand({
    CiphertextBlob: Buffer.from(ciphertext, 'base64'),
  });

  const response = await kms.send(command);
  return response.Plaintext.toString();
}
```

