### 4. **Secret Rotation Strategy**

```javascript
const redis = require('redis');
const axios = require('axios');

class SecretRotator {
  constructor(options) {
    this.cache = redis.createClient();
    this.secretsManagerUrl = options.secretsManagerUrl;
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = await this.cache.get(`secret:${secretName}`);
    if (cached) {
      return JSON.parse(cached);
    }

    // Fetch from secrets manager
    const freshSecret = await this.fetchFromSecretsManager(secretName);

    // Cache with TTL
    await this.cache.setex(
      `secret:${secretName}`,
      300, // 5 minutes
      JSON.stringify(freshSecret)
    );

    return freshSecret;
  }

  async fetchFromSecretsManager(secretName) {
    const response = await axios.get(
      `${this.secretsManagerUrl}/secrets/${secretName}`,
      {
        headers: {
          Authorization: `Bearer ${process.env.SECRET_ACCESS_TOKEN}`,
        },
      }
    );
    return response.data;
  }

  // Periodically refresh secrets
  startRotation(intervalMinutes = 60) {
    setInterval(async () => {
      // Force refresh of cached secrets
      await this.cache.flushdb();
      console.log('Secrets rotated');
    }, intervalMinutes * 60 * 1000);
  }
}

const rotator = new SecretRotator({
  secretsManagerUrl: process.env.SECRETS_MANAGER_URL,
});
rotator.startRotation(60);
```

