DATABASE_URL=postgres://user:pass@host:5432/db

# Use separate values:
DB_HOST=db.internal
DB_PORT=5432
DB_NAME=production
DB_USER=app_user  # Not 'admin'
DB_PASS=${DB_PASSWORD}  # From secrets manager
