## ✅ Secure Implementation: AWS Secrets Manager

### Recommended Architecture

```
┌─────────────────┐
│   Application   │
│   (EC2/Lambda)  │
└────────┬────────┘
         │
         │ Temporary Cred
         │ via IAM Role
         ▼
┌──────────────────────────┐
│   AWS Secrets Manager    │
│                          │
│  • Encrypted at rest     │
│  • Auto rotation         │
│  • Audit logging         │
│  • Fine-grained access   │
│  • Version history       │
└──────────────────────────┘
```

---

### Implementation Code

#### 1. Install Dependencies

```bash
npm install @aws-sdk/client-secrets-manager dotenv
```

#### 2. Create Secrets Manager Utility

```javascript
// lib/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
    });
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName, useCache = true) {
    // Check cache first
    if (useCache && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        return cached.value;
      }
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      const secret = response.SecretString
        ? JSON.parse(response.SecretString)
        : response.SecretBinary;

      // Cache the result
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now(),
      });

      return secret;
    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        throw new Error(`Secret not found: ${secretName}`);
      }
      throw new Error(`Failed to retrieve secret: ${error.message}`);
    }
  }

  // Helper to get nested value
  async get(secretName, key) {
    const secret = await this.getSecret(secretName);
    return secret[key];
  }

  // Clear cache (useful for testing)
  clearCache() {
    this.cache.clear();
  }
}

module.exports = new SecretManager();
```

#### 3. Update Application Entry Point

```javascript
// app.js - Secure version with secrets manager
require('dotenv').config(); // For local dev with .env only

const express = require('express');
const secretManager = require('./lib/secrets');

const app = express();

// Validate and load secrets on startup
async function initializeApp() {
  const requiredSecrets = [
    { name: 'production/database', env: 'DATABASE_URL' },
    { name: 'production/stripe', key: 'secret_key', env: 'STRIPE_SECRET_KEY' },
    { name: 'production/anthropic', key: 'api_key', env: 'ANTHROPIC_API_KEY' },
    { name: 'production/app', key: 'jwt_secret', env: 'JWT_SECRET' },
  ];

  const missingSecrets = [];

  for (const secret of requiredSecrets) {
    try {
      if (process.env.NODE_ENV === 'production') {
        // Use AWS Secrets Manager in production
        const value = secret.key
          ? await secretManager.get(secret.name, secret.key)
          : await secretManager.getSecret(secret.name);

        process.env[secret.env] = value;
      } else {
        // Local development - validate .env exists
        if (!process.env[secret.env]) {
          missingSecrets.push(secret.env);
        }
      }
    } catch (error) {
      missingSecrets.push(`${secret.name} (${secret.env})`);
    }
  }

  if (missingSecrets.length > 0) {
    console.error('❌ Missing required secrets:');
    missingSecrets.forEach(s => console.error(`   - ${s}`));
    process.exit(1);
  }

  console.log('✅ All secrets loaded successfully');

  // Start the server
  startServer();
}

function startServer() {
  // ... your application code
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} (mode: ${process.env.NODE_ENV})`);
  });
}

// Initialize
initializeApp().catch(error => {
  console.error('Failed to initialize application:', error);
  process.exit(1);
});

module.exports = app;
```

