## ✅ Alternative: Vault (HashiCorp) Implementation

### lib/secrets-vault.js

```javascript
const NodeVault = require('node-vault');

class VaultSecretManager {
  constructor() {
    this.client = NodeVault({
      endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
      token: process.env.VAULT_TOKEN,
    });
    this.cache = new Map();
  }

  async getSecret(path) {
    try {
      const response = await this.client.read(path);
      return response.data.data;
    } catch (error) {
      throw new Error(`Failed to retrieve secret from Vault: ${error.message}`);
    }
  }

  async get(path, key) {
    const secret = await this.getSecret(path);
    return secret[key];
  }
}

module.exports = new VaultSecretManager();
```

