# Pre-commit hook
#!/bin/bash
# .git/hooks/pre-commit

# Check for common secret patterns
FILES=$(git diff --cached --name-only --diff-filter=ACM | grep "\.env$")
if [ -n "$FILES" ]; then
  echo "❌ Attempting to commit .env files!"
  echo "These files should never be committed to version control."
  exit 1
fi

# Check for secrets in committed files
if git diff --cached | grep -Ei "(password|secret|key|token)\s*=\s*['\"]"; then
  echo "❌ Possible_secret detected in commit!"
