### 4.2 Create Secrets Manager Utility

```javascript
// lib/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretManager {
  constructor(options = {}) {
    this.client = new SecretsManagerClient({
      region: options.region || process.env.AWS_REGION || 'us-east-1',
    });
    this.cache = new Map();
    this.cacheTTL = options.cacheTTL || 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName, options = {}) {
    const { useCache = true, maxAge } = options;

    // Check cache
    const key = secretName;
    if (useCache && this.cache.has(key)) {
      const cached = this.cache.get(key);
      const effectiveAge = maxAge || this.cacheTTL;
      if (Date.now() - cached.timestamp < effectiveAge) {
        return cached.value;
      }
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      let secret;
      if (response.SecretString) {
        try {
          secret = JSON.parse(response.SecretString);
        } catch {
          secret = response.SecretString;
        }
      } else if (response.SecretBinary) {
        secret = response.SecretBinary.toString();
      }

      // Cache the result
      if (useCache) {
        this.cache.set(key, {
          value: secret,
          timestamp: Date.now(),
        });
      }

      return secret;
    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        throw new Error(`❌ Secret not found: ${secretName}`);
      }
      if (error.name === 'AccessDeniedException') {
        throw new Error(`❌ Access denied to secret: ${secretName}. Check IAM permissions.`);
      }
      throw new Error(`❌ Failed to retrieve secret: ${error.message}`);
    }
  }

  async get(secretName, key) {
    const secret = await this.getSecret(secretName);
    if (typeof secret === 'string') {
      return secret;
    }
    if (!secret.hasOwnProperty(key)) {
      throw new Error(`❌ Key "${key}" not found in secret "${secretName}"`);
    }
    return secret[key];
  }

  clearCache() {
    this.cache.clear();
  }
}

// Singleton instance
const instance = new SecretManager();

module.exports = instance;
module.exports.SecretManager = SecretManager;
```

### 4.3 Create Configuration Loader

```javascript
// config/index.js
const secretManager = require('../lib/secrets');

async function loadConfig() {
  const config = {
    // Non-secret config
    env: process.env.NODE_ENV || 'development',
    port: parseInt(process.env.PORT) || 3000,
    logLevel: process.env.LOG_LEVEL || 'info',

    // URLs (construct from secrets)
    databaseUrl: null,
    stripeKey: null,
    anthropicKey: null,
    jwtSecret: null,
  };

  // Load secrets based on environment
  if (config.env === 'production') {
    console.log('🔒 Loading secrets from AWS Secrets Manager...');

    try {
      // Database credentials
      const dbSecret = await secretManager.getSecret('production/database');
      config.databaseUrl = `postgres://${dbSecret.username}:${dbSecret.password}@${dbSecret.host}:${dbSecret.port}/${dbSecret.database}`;

      // Stripe credentials
      config.stripeKey = await secretManager.get('production/stripe', 'secret_key');

      // Anthropic API key
      config.anthropicKey = await secretManager.get('production/anthropic', 'api_key');

      // JWT secret
      config.jwtSecret = await secretManager.get('production/app', 'jwt_secret');

      console.log('✅ All secrets loaded from Secrets Manager');
    } catch (error) {
      console.error('❌ Failed to load secrets:', error.message);
      throw error;
    }

  } else {
    // Development/Testing - use .env or environment variables
    console.log('🔓 Loading secrets from environment variables...');

    const requiredVars = {
      DATABASE_URL: 'databaseUrl',
      STRIPE_SECRET_KEY: 'stripeKey',
      ANTHROPIC_API_KEY: 'anthropicKey',
      JWT_SECRET: 'jwtSecret',
    };

    const missing = [];

    for (const [envVar, configKey] of Object.entries(requiredVars)) {
      const value = process.env[envVar];
      if (!value) {
        missing.push(envVar);
      } else {
        config[configKey] = value;
      }
    }

    if (missing.length > 0) {
      console.warn('⚠️  Missing required environment variables:', missing);
      console.warn('   Using defaults for development (DO NOT USE IN PRODUCTION!)');

      // Provide safe defaults for dev only
      config.databaseUrl = config.databaseUrl || 'postgres://dev:dev@localhost:5432/dev';
      config.stripeKey = config.stripeKey || 'REDACTED_STRIPE_TEST';
      config.anthropicKey = config.anthropicKey || 'REDACTED_ANTHROPIC_KEY';
      config.jwtSecret = config.jwtSecret || 'dev-secret-do-not-use-in-production';
    } else {
      console.log('✅ All secrets loaded from environment variables');
    }
  }

  return config;
}

let cachedConfig = null;

async function getConfig() {
  if (!cachedConfig) {
    cachedConfig = await loadConfig();
  }
  return cachedConfig;
}

module.exports = { getConfig, loadConfig };
```

