### Option 1: AWS Secrets Manager (Recommended for Cloud)

```javascript
// config/secrets.js
require('dotenv').config(); // Fallback for local development

const AWS = require('aws-sdk');
const client = new AWS.SecretsManager();

let secretsCache = null;
const SECRETS_CACHE_TTL = 5 * 60 * 1000; // 5 minutes

async function getSecret(secretName) {
  // Try cache first
  if (secretsCache && Date.now() - secretsCache.timestamp < SECRETS_CACHE_TTL) {
    return secretsCache.data[secretName];
  }

  try {
    const response = await client.getSecretValue({ SecretId: secretName }).promise();

    let secret;
    if ('SecretString' in response) {
      secret = JSON.parse(response.SecretString);
    } else {
      secret = JSON.parse(Buffer.from(response.SecretBinary, 'base64').toString());
    }

    // Update cache
    secretsCache = {
      data: secret,
      timestamp: Date.now()
    };

    return secret[secretName];
  } catch (error) {
    console.error(`Error fetching secret ${secretName}:`, error.message);

    // Fallback to environment variables for local development
    if (process.env.NODE_ENV === 'development') {
      return process.env[secretName];
    }

    throw error;
  }
}

async function getAllSecrets() {
  const secretNames = [
    'jwt-secret',      // Maps to AWS secret name
    'database-url',
    'api-key',
    'oauth-client-secret'
  ];

  const secrets = {};
  for (const name of secretNames) {
    secrets[name.toUpperCase().replace(/-/g, '_')] = await getSecret(name);
  }

  return secrets;
}

// Validate required secrets at startup
function validateSecrets(secrets) {
  const required = ['JWT_SECRET'];
  const missing = required.filter(key => !secrets[key]);

  if (missing.length > 0) {
    throw new Error(`Missing required secrets: ${missing.join(', ')}`);
  }

  // Validate secret complexity
  if (secrets.JWT_SECRET && secrets.JWT_SECRET.length < 32) {
    console.warn('WARNING: JWT_SECRET should be at least 32 characters');
  }
}

module.exports = { getSecret, getAllSecrets, validateSecrets };
```

