// config/env-loader.js
const fs = require('fs');
const path = require('path');

function loadEnv() {
  const envFile = path.join(__dirname, '../.env.local');

  if (!fs.existsSync(envFile)) {
    throw new Error('.env.local file not found. Copy .env.example to .env.local and configure your secrets.');
  }

  // Verify file permissions (only owner readable)
  const stats = fs.statSync(envFile);
  const modeOctal = (stats.mode & parseInt('777', 8)).toString(8);

  if (modeOctal !== '600' && modeOctal !== '400') {
    console.warn(`WARNING: .env.local has insecure permissions: ${modeOctal}. Run: chmod 600 .env.local`);
  }

  require('dotenv').config({ path: envFile });

  // Validate required environment variables
  const required = ['JWT_SECRET', 'DATABASE_URL'];
  const missing = required.filter(key => !process.env[key]);

  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }

  return process.env;
}

module.exports = { loadEnv };
