```javascript
// scripts/identify-secrets.js
// This script identifies WHICH secrets exist without reading their values

const fs = require('fs');
const path = require('path');

function findEnvFiles() {
  const envFiles = [];

  function searchDir(dir) {
    const files = fs.readdirSync(dir);
    for (const file of files) {
      const fullPath = path.join(dir, file);
      const stat = fs.statSync(fullPath);

      if (stat.isDirectory() && !file.includes('node_modules')) {
        searchDir(fullPath);
      } else if (file.match(/^\.env/)) {
        envFiles.push(fullPath);
      }
    }
  }

  searchDir(process.cwd());
  return envFiles;
}

function extractSecretNames(envPath) {
  const content = fs.readFileSync(envPath, 'utf8');
  const lines = content.split('\n');
  const secrets = [];

  for (const line of lines) {
    // Skip comments and empty lines
    if (line.trim().startsWith('#') || !line.trim() || !line.includes('=')) {
      continue;
    }

    // Extract variable name only (not the value)
    const varName = line.split('=')[0].trim();

    // Identify likely secrets based on naming patterns
    const secretPatterns = [
      /secret/i,
      /password/i,
      /key/i,
      /token/i,
      /api[_-]?key/i,
      /private/i,
      /credential/i,
      /auth/i
    ];

    const isLikelySecret = secretPatterns.some(pattern => pattern.test(varName));

    if (isLikelySecret) {
      secrets.push({
        name: varName,
        source: path.basename(envPath),
        priority: determinePriority(varName)
      });
    }
  }

  return secrets;
}

function determinePriority(varName) {
  const highPriority = ['JWT_SECRET', 'DATABASE_PASSWORD', 'API_KEY'];
  const mediumPriority = ['SESSION_SECRET', 'OAUTH_SECRET', 'ENCRYPTION_KEY'];

  if (highPriority.includes(varName)) return 'HIGH';
  if (mediumPriority.includes(varName)) return 'MEDIUM';
  return 'LOW';
}

// Generate rotation report
function generateRotationReport() {
  const envFiles = findEnvFiles();
  const allSecrets = [];

  for (const envFile of envFiles) {
    try {
      const secrets = extractSecretNames(envFile);
      allSecrets.push(...secrets);
    } catch (error) {
      console.error(`Error reading ${envFile}:`, error.message);
    }
  }

  // Remove duplicates
  const uniqueSecrets = Array.from(
    new Map(allSecrets.map(s => [s.name, s])).values()
  );

  // Sort by priority
  const priorityOrder = { HIGH: 1, MEDIUM: 2, LOW: 3 };
  uniqueSecrets.sort((a, b) => priorityOrder[a.priority] - priorityOrder[b.priority]);

  console.log('\n=== Secrets Rotation Inventory ===\n');
  console.log(`Found ${uniqueSecrets.length} secrets requiring rotation:\n`);
  console.log('PRIORITY | SECRET NAME          | SOURCE FILE');
  console.log('---------|----------------------|-------------');
  uniqueSecrets.forEach(s => {
    console.log(`${s.priority.padEnd(8)} | ${s.name.padEnd(20)} | ${s.source}`);
  });

  return uniqueSecrets;
}

generateRotationReport();
```

