### 4. No Input Validation (A03:2021 - Injection)

**Severity:** MEDIUM  
**OWASP Category:** A03:2021 - Injection

There's no input validation on any incoming requests. While currently simple, this creates a foundation for future vulnerabilities.

**Current Issue:**
```javascript
// No validation of query parameters or request body
app.get('/users', (req, res) => {
  res.json([...]);
});
```

**Recommended Fix:**
```javascript
const { body, query, param, validationResult } = require('express-validator');

// Validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

// Example with validation
app.get('/users/:id', 
  param('id').isInt().withMessage('ID must be an integer'),
  query('fields').optional().isIn(['id', 'name', 'email']).withMessage('Invalid field'),
  validateRequest,
  (req, res) => {
    const userId = parseInt(req.params.id);
    const user = getUserById(userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    // Filter fields based on query parameter
    const allowedFields = req.query.fields ? req.query.fields.split(',') : ['id', 'name'];
    const filteredUser = {};
    allowedFields.forEach(field => {
      if (user[field] !== undefined) {
        filteredUser[field] = user[field];
      }
    });

    res.json(filteredUser);
  }
);

// POST request example with body validation
app.post('/users',
  body('name').trim().isLength({ min: 2, max: 100 }).escape().withMessage('Invalid name'),
  body('email').trim().isEmail().normalizeEmail().withMessage('Invalid email'),
  validateRequest,
  (req, res) => {
    // Process validated input
    createUser(req.body);
    res.status(201).json({ message: 'User created' });
  }
);
```

