### Option 2: AWS Secrets Manager (Recommended for AWS)

```javascript
const AWS = require('aws-sdk');
const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

// Initialize Secrets Manager client
const secretsClient = new SecretsManager({ region: process.env.AWS_REGION });

/**
 * Load secrets from AWS Secrets Manager
 * @param {string} secretName - Name of the secret in AWS Secrets Manager
 * @returns {Promise<Object>} - Parsed secret value
 */
async function loadSecrets(secretName) {
  try {
    const response = await secretsClient.getSecretValue({
      SecretId: secretName
    });

    const secretString = response.SecretString;

    if (!secretString) {
      throw new Error('Secret string is empty');
    }

    return JSON.parse(secretString);
  } catch (error) {
    console.error(`Error loading secret "${secretName}":`, error);
    throw error;
  }
}

// Initialize application with secrets
async function initializeApp() {
  try {
    // Load secrets from AWS Secrets Manager
    const secrets = await loadSecrets('prod/myapp/secrets');

    // Validate secrets
    const requiredSecrets = ['jwt_secret', 'database_url', 'session_secret'];
    const missingSecrets = requiredSecrets.filter(key => !secrets[key]);

    if (missingSecrets.length > 0) {
      throw new Error(`Missing required secrets: ${missingSecrets.join(', ')}`);
    }

    // Create Express app with loaded secrets
    const app = express();

    // Use secrets in configuration
    app.set('jwt_secret', secrets.jwt_secret);
    app.set('database_url', secrets.database_url);
    app.set('session_secret', secrets.session_secret);

    // ... rest of application setup

    return app;
  } catch (error) {
    console.error('Failed to initialize application:', error);
    process.exit(1);
  }
}

// Start the application
initializeApp().then(app => {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
});
```

