async function loadSecretsFromVault() {
  const vault = nodeVault({
    endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
    token: process.env.VAULT_TOKEN // This should come from EC2 IAM role or Kubernetes auth
  });

