For containerized deployments, use environment variables with proper validation:

```javascript
const Joi = require('joi');

// Define schema for environment variables
const envSchema = Joi.object({
  // Server
  NODE_ENV: Joi.string()
    .valid('development', 'staging', 'production')
    .default('development'),
  PORT: Joi.number().default(3000),

  // Security
  JWT_SECRET: Joi.string()
    .min(32)
    .required()
    .description('JWT signing secret - must be at least 32 characters'),
  SESSION_SECRET: Joi.string()
    .min(32)
    .required()
    .description('Session encryption secret'),

  // Database
  DATABASE_URL: Joi.string()
    .uri()
    .required()
    .description('Database connection string'),

  // CORS
  ALLOWED_ORIGINS: Joi.string()
    .required()
    .description('Comma-separated list of allowed origins'),

  // External Services
  API_KEY: Joi.string()
    .when('NODE_ENV', {
      is: 'production',
      then: Joi.required(),
      otherwise: Joi.optional()
    })
}).unknown(); // Allow additional env vars

// Validate and extract environment variables
const { error, value: envVars } = envSchema.validate(process.env);

if (error) {
  throw new Error(`Environment variable validation error: ${error.message}`);
}

// Export validated config
module.exports = {
  env: envVars.NODE_ENV,
  port: envVars.PORT,
  jwt: {
    secret: envVars.JWT_SECRET,
    expiresIn: '1h'
  },
  session: {
    secret: envVars.SESSION_SECRET,
    maxAge: 3600000
  },
  database: {
    url: envVars.DATABASE_URL
  },
  cors: {
    allowedOrigins: envVars.ALLOWED_ORIGINS.split(',')
  },
  apiKey: envVars.API_KEY
};
