### Automated Rotation Setup

```javascript
# scripts/rotate-secrets.js

const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager();

async function rotateSecret(secretName) {
  console.log(`🔄 Starting rotation for: ${secretName}`);

  try {
    // Step 1: Create new version
    const newSecret = generateNewSecret();

    await secretsManager.putSecretValue({
      SecretId: secretName,
      SecretString: JSON.stringify(newSecret),
      VersionStages: ['AWSCURRENT']
    }).promise();

    console.log(`✅ Rotated: ${secretName}`);

    // Step 2: Update dependent services
    await updateServiceCredentials(secretName, newSecret);

    // Step 3: Invalidate application cache
    require('../config/secrets').invalidateCache(secretName);

    return true;
  } catch (error) {
    console.error(`❌ Rotation failed for ${secretName}:`, error.message);
    // Alert operations team
    await alertOnError(secretName, error);
    throw error;
  }
}

function generateNewSecret() {
  const crypto = require('crypto');
  return {
    password: crypto.randomBytes(32).toString('base64'),
    apiKey: `sk-${crypto.randomBytes(24).toString('hex')}`,
    rotatedAt: new Date().toISOString()
  };
}

async function updateServiceCredentials(secretName, credentials) {
  // Update database connections, API integrations, etc.
  console.log(`📡 Updating services for: ${secretName}`);
}

async function alertOnError(secretName, error) {
  // Send alert to PagerDuty, Slack, etc.
  console.log(`🚨 Alert: Secret rotation failed - ${secretName}`);
}

module.exports = { rotateSecret };
