// config/secrets.js
const AWS = require('aws-sdk');
const ssm = new AWS.SSM();

class SecretsManager {
  async getSecret(secretName) {
    try {
      const data = await ssm.getParameter({
        Name: secretName,
        WithDecryption: true
      }).promise();

      return data.Parameter.Value;
    } catch (error) {
      console.error(`Error fetching secret ${secretName}:`, error);
      throw error;
    }
  }

  async loadAllSecrets() {
    const secrets = {
      databaseUrl: await this.getSecret('/app/production/database/url'),
      awsAccessKeyId: await this.getSecret('/app/production/aws/access-key-id'),
      awsSecretAccessKey: await this.getSecret('/app/production/aws/secret-access-key'),
      anthropicApiKey: await this.getSecret('/app/production/anthropic/api-key'),
      stripeSecretKey: await this.getSecret('/app/production/stripe/secret-key'),
      logfireToken: await this.getSecret('/app/production/logfire/token')
    };

    return secrets;
  }
}

module.exports = new SecretsManager();
