  async loadAppSecrets() {
    const secrets = await this.getSecret('secret/data/app/production');
    return {
      ...secrets
    };
  }

  // Implement automatic secret rotation
  async setupSecretRotation(secretPath, ttl = '24h') {
    await nodeVault.write(`${secretPath}/config`, {
      max_ttl: ttl,
      ttl: ttl
    });
  }
}

