// SECURE VERSION - Comprehensive security implementation
// This demonstrates security best practices for Express.js applications

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const timeout = require('connect-timeout');
const { body, validationResult } = require('express-validator');

// Secure configuration
const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Security Headers (OWASP A05: Security Misconfiguration)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  noSniff: true,
  frameguard: { action: 'deny' },
  xssFilter: true,
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));

// 2. Rate Limiting (OWASP A07: Authentication Failures)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => req.ip === '127.0.0.1' // Skip for localhost
});
app.use(limiter);

// Strict rate limiting for auth-related endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: { error: 'Too many authentication attempts, please try again later.' }
});

// 3. CORS Configuration (OWASP A01: Broken Access Control)
const allowedOrigins = process.env.ALLOWED_ORIGINS
  ? process.env.ALLOWED_ORIGINS.split(',')
  : ['http://localhost:3000'];

app.use(cors({
  origin: (origin, callback) => {
    // Allow requests with no origin (like mobile apps or curl requests)
    if (!origin) return callback(null, true);

    if (allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS policy'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400 // 24 hours
}));

// 4. Request Size Limits & Timeout (OWASP A08: Integrity Failures)
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ limit: '1mb', extended: true }));
app.use(timeout('30s'));

// 5. Request Logging (Security Monitoring)
app.use(morgan('combined'));
app.use((req, res, next) => {
  // Log suspicious patterns
  const suspiciousPatterns = [
    /<script/i,
    /javascript:/i,
    /onerror=/i,
    /onload=/i,
    /\.\./,
    /%2e%2e/i
  ];

  const url = req.url.toLowerCase();
  const isSuspicious = suspiciousPatterns.some(pattern => pattern.test(url));

  if (isSuspicious) {
    console.error(`[SECURITY] Suspicious request from ${req.ip}: ${req.method} ${req.url}`);
  }

  // Track request start time for monitoring
  req.startTime = Date.now();
  next();
});

// 6. Input Sanitization
const sanitizeInput = (req, res, next) => {
  const sanitize = (obj) => {
    if (!obj || typeof obj !== 'object') return obj;

    for (const key in obj) {
      if (typeof obj[key] === 'string') {
        // Remove potentially dangerous characters
        obj[key] = obj[key]
          .replace(/[<>]/g, '') // Remove HTML brackets
          .trim();
      } else if (typeof obj[key] === 'object') {
        sanitize(obj[key]);
      }
    }
    return obj;
  };

  if (req.body) sanitize(req.body);
  if (req.query) sanitize(req.query);
  if (req.params) sanitize(req.params);

  next();
};
app.use(sanitizeInput);

// ============================================
// VALIDATION MIDDLEWARE
// ============================================

const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};

// ============================================
// AUTHENTICATION MIDDLEWARE (Template)
// ============================================

// Note: Implement proper JWT authentication in production
const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({
      error: 'Authentication required',
      code: 'AUTH_MISSING'
    });
  }

  const token = authHeader.substring(7);

  try {
    // Verify JWT token (implement actual verification)
    // const decoded = jwt.verify(token, process.env.JWT_SECRET);
    // req.user = decoded;

    // For demo, mock user
    req.user = { id: 1, role: 'user', email: 'user@example.com' };

    next();
  } catch (error) {
    return res.status(403).json({
      error: 'Invalid or expired token',
      code: 'AUTH_INVALID'
    });
  }
};

const requireRole = (...roles) => {
  return (req, res, next) => {
    if (!req.user || !roles.includes(req.user.role)) {
      return res.status(403).json({
        error: 'Insufficient privileges',
        code: 'AUTH_FORBIDDEN'
      });
    }
    next();
  };
};

// ============================================
// SECURITY UTILITIES
// ============================================

function logSecurityEvent(eventType, details) {
  const logEntry = {
    timestamp: new Date().toISOString(),
    event: eventType,
    ...details
  };
  console.error('[SECURITY]', JSON.stringify(logEntry));

  // In production, send to SIEM/monitoring service
  // Example: sendToSIEM(logEntry);
}

function halTimeout(req, res, next) {
  if (!req.timedout) next();
}
app.use(halTimeout);

// ============================================
// ROUTES
// ============================================

// Health check with restrictions
app.get('/health', (req, res) => {
  // Additional health metrics can be added
  const isHealthy = true;

  res.status(isHealthy ? 200 : 503).json({
    status: isHealthy ? 'ok' : 'error',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Users API - Protected endpoint
app.get('/users', authenticate, requireRole('admin'), (req, res) => {
  logSecurityEvent('USER_DATA_ACCESS', {
    userId: req.user.id,
    endpoint: '/users',
    ip: req.ip,
    userAgent: req.get('user-agent')
  });

