    // );

    res.status(201).json({
      message: 'User created',
      user: {
        id: 3,
        name: req.body.name,
        email: req.body.email
      }
    });
  }
);

// Example: Login with rate limiting
app.post('/login', authLimiter, (req, res) => {
  // Log login attempt
  logSecurityEvent('LOGIN_ATTEMPT', {
    ip: req.ip,
    email: req.body.email,
    userAgent: req.get('user-agent')
  });

  // In production, implement proper password verification with bcrypt/scrypt/argon2
  const { email, password } = req.body;

  // Validate credentials
  if (!email || !password) {
    return res.status(400).json({
      error: 'Email and password required'
    });
  }

  // Simulate authentication (use bcrypt.compare in production)
  // if (await bcrypt.compare(password, user.hash)) {...}

  res.json({
    message: 'Login successful',
    // token: generateJWT(user) // Generate proper JWT in production
  });
});

// ============================================
// ERROR HANDLING
// ============================================

// Handle timeout errors
app.use((req, res, next) => {
  if (req.timedout) {
    return res.status(504).json({
      error: 'Request timeout',
      code: 'TIMEOUT'
    });
  }
  next();
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
    method: req.method
  });
});

// Global error handler (MUST be last)
app.use((err, req, res, next) => {
  // Log full error for debugging
  console.error('Error:', err);

  // Security: Don't expose stack traces in production
  const isDevelopment = process.env.NODE_ENV !== 'production';

  // Log security-relevant errors
  if (err.status === 401 || err.status === 403) {
    logSecurityEvent('AUTH_ERROR', {
      error: err.message,
      ip: req.ip,
      path: req.path
    });
  }

  res.status(err.status || 500).json({
    error: {
      message: isDevelopment ? err.message : 'Internal server error',
      code: err.code || 'INTERNAL_ERROR',
      ...(isDevelopment && { stack: err.stack })
    }
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;

// In production, use HTTPS
if (process.env.NODE_ENV === 'production' && !process.env.HTTPS_DISABLE) {
  const fs = require('fs');
