```javascript
// config/secrets.js - Secure secret management
const { getConfig } = require('@aws-sdk/property-provider');
const { fromNodeProviderChain } = require('@aws-sdk/credential-providers');

class SecretManager {
  constructor() {
    this.cache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTimeout) {
      return cached.value;
    }

    // Load from appropriate source based on environment
    let value;
    if (process.env.NODE_ENV === 'production') {
      value = await this.loadFromSecretsManager(secretName);
    } else if (process.env.NODE_ENV === 'test') {
      value = await this.loadFromTestEnv(secretName);
    } else {
      value = await this.loadFromEnvFile(secretName);
    }

    // Validate secret exists
    if (!value) {
      throw new Error(`Required secret not found: ${secretName}`);
    }

    // Cache the value
    this.cache.set(secretName, { value, timestamp: Date.now() });
    return value;
  }

  async loadFromSecretsManager(secretName) {
    // AWS Secrets Manager, Azure Key Vault, etc.
    // Implementation depends on provider
    const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
    const client = new SecretsManagerClient({ region: process.env.AWS_REGION });
    const response = await client.send(new GetSecretValueCommand({ SecretId: secretName }));
    return JSON.parse(response.SecretString);
  }

  async loadFromTestEnv(secretName) {
    // In test environments, validate test key format
    const value = process.env[secretName];
    if (!value) return null;

    // Ensure test keys have test indicators
    if (secretName.includes('API_KEY') && !value.includes('test')) {
      throw new Error(`Test environment requires test keys for: ${secretName}`);
    }
    return value;
  }

  async loadFromEnvFile(secretName) {
    // Development only - load from .env.local (never .env or committed files)
    if (process.env.NODE_ENV !== 'development') {
      throw new Error('Env file loading only allowed in development');
    }
    return process.env[secretName];
  }
}

module.exports = new SecretManager();
```

