  windowMs: 15 * 60 * 1000,
  max: 100,
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: { error: 'Rate limit exceeded for this endpoint.' },
});

app.use(limiter);

// Body parsing with size limits
app.use(express.json({ limit: '1mb', strict: true }));
app.use(express.urlencoded({ extended: true, limit: '1mb' }));

// Request logging
app.use(morgan('combined', {
  stream: { write: message => logger.info(message.trim()) }
}));

// Input sanitization middleware
app.use((req, res, next) => {
  const suspiciousPatterns = [
    /\.\./,
    /<script>/i,
    /union.*select/i,
    /javascript:/i
  ];

  const checkObject = (obj) => {
    if (!obj || typeof obj !== 'object') return false;
    const str = JSON.stringify(obj);
    return suspiciousPatterns.some(pattern => pattern.test(str));
  };

  if (checkObject(req.query) || checkObject(req.body)) {
    logger.warn({
      type: 'SECURITY_EVENT',
      event: 'SUSPICIOUS_INPUT',
      ip: req.ip,
      userAgent: req.get('user-agent'),
      path: req.path,
      method: req.method,
      query: req.query,
    });
    return res.status(400).json({ 
      error: 'Invalid request'
    });
  }

  // Sanitize query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        req.query[key] = req.query[key].trim();
      }
    });
  }

  next();
});

// Health check endpoint
app.get('/health', (req, res) => {
  const authHeader = req.headers['x-health-secret'];
  if (NODE_ENV === 'production' && 
      process.env.HEALTH_SECRET && 
      authHeader !== process.env.HEALTH_SECRET) {
    logger.warn({ type: 'UNAUTHORIZED_HEALTH_CHECK', ip: req.ip });
    return res.status(403).json({ status: 'unauthorized' });
  }
  res.json({ status: 'ok' });
});

// Users endpoint - requires authentication in the example
// For demonstration, this is using rate limiting without auth
app.get('/users', strictLimiter, (req, res) => {
  // Validate pagination parameters
  let page = parseInt(req.query.page);
  let limit = parseInt(req.query.limit);

  if (isNaN(page) || page < 1) page = 1;
  if (isNaN(limit) || limit < 1 || limit > 100) limit = 10;

  const allUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Return paginated users (note: in production, session/auth gates are recommended)
  const startIndex = (page - 1) * limit;
  const endIndex = startIndex + limit;
  const paginatedUsers = allUsers.slice(startIndex, endIndex);

  res.json({
    data: paginatedUsers,
    pagination: {
      page,
      limit,
      total: allUsers.length,
      totalPages: Math.ceil(allUsers.length / limit)
    }
  });
});

// 404 handler
app.use((req, res) => {
  logger.info({ type: 'NOT_FOUND', path: req.path, ip: req.ip });
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler
app.use((err, req, res, next) => {
  logger.error({
    type: 'ERROR',
    message: err.message,
    path: req.path,
    method: req.method,
    ip: req.ip,
    ...(NODE_ENV === 'development' && { stack: err.stack })
  });

  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    error: {
      message: NODE_ENV === 'production' 
        ? 'Internal Server Error' 
        : err.message
    }
  });
});

// Start server
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running in ${NODE_ENV} mode on port ${PORT}`);
  });
}

module.exports = app;
```

