#### Option 1: AWS Secrets Manager (Recommended for AWS deployments)

```javascript
const AWS = require('aws-sdk');
const { SQS } = require('@aws-sdk/client-sqs');

// Initialize Secrets Manager client
const secretsClient = new AWS.SecretsManager({ region: process.env.AWS_REGION });

async function getSecret(secretName) {
  try {
    const data = await secretsClient.getSecretValue({ SecretId: secretName }).promise();
    if ('SecretString' in data) {
      return JSON.parse(data.SecretString);
    }
    throw new Error('Secret binary not supported');
  } catch (err) {
    throw new Error(`Failed to retrieve secret ${secretName}: ${err.message}`);
  }
}

// Load secrets at startup
async function loadSecrets() {
  const secrets = await getSecret('myapp/production');

  // Set environment variables
  process.env.DATABASE_URL = secrets.database_url;
  process.env.AWS_SECRET_ACCESS_KEY = secrets.aws_secret_key;
  process.env.STRIPE_SECRET_KEY = secrets.stripe_key;
  process.LOGFIRE_TOKEN = secrets.logfire_token;
}

// Initialize app only after secrets are loaded
const express = require('express');
const app = express();

// ... rest of your app

loadSecrets().then(() => {
  app.listen(3000, () => {
    console.log('Server running with secrets loaded from AWS Secrets Manager');
  });
}).catch(err => {
  console.error('Failed to load secrets:', err);
  process.exit(1);
});
```

#### Option 2: HashiCorp Vault

```javascript
const nodeVault = require('node-vault');

async function loadSecretsFromVault() {
  const vault = nodeVault({
    endpoint: process.env.VAULT_ADDR,
    token: process.env.VAULT_TOKEN // This should come from instance metadata or KMS
  });

  try {
    const databaseSecrets = await vault.read('secret/data/myapp/database');
    const apiSecrets = await vault.read('secret/data/myapp/apis');

    return {
      database: databaseSecrets.data.data,
      apis: apiSecrets.data.data
    };
  } catch (err) {
    throw new Error(`Vault error: ${err.message}`);
  }
}
```

#### Option 3: Environment Variables with .env Framework (Development Only)

