## **✅ OPTION 1: AWS Secrets Manager (Recommended for Cloud)**

```javascript
// config/secrets.js
const AWS = require('aws-sdk');
const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManager({ 
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const response = await this.client.getSecretValue({
        SecretId: secretName
      });

      let secretString;
      if (response.SecretString) {
        secretString = response.SecretString;
      } else {
        secretString = Buffer.from(response.SecretBinary, 'base64').toString();
      }

      // Parse JSON secrets or return as string
      const secretValue = secretString.startsWith('{') 
        ? JSON.parse(secretString) 
        : secretString;

      // Cache the result
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Error fetching secret ${secretName}:`, error.message);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  async invalidateCache(secretName) {
    if (secretName) {
      this.cache.delete(secretName);
    } else {
      this.cache.clear();
    }
  }
}

module.exports = new SecretsManager();
```

