// config/production.js
const secretsManager = require('./secrets-manager');

class Config {
  constructor() {
    this.secrets = {};
  }

  async initialize() {
    const env = process.env.NODE_ENV;

    if (env === 'production') {
      // Use AWS Secrets Manager in production
      await this.loadFromSecretsManager();
    } else {
      // Use environment variables in dev/staging
      await this.loadFromEnv();
    }

    this.validate();
  }

  async loadFromSecretsManager() {
    try {
      // Load all required secrets in parallel
      const [dbSecrets, awsSecrets, stripeSecret] = await Promise.all([
        secretsManager.getSecret('prod/database/config'),
        secretsManager.getSecret('prod/aws/credentials'),
        secretsManager.getSecret('prod/stripe/api-key'),
      ]);

      this.secrets = {
        database: dbSecrets,
        aws: awsSecrets,
        stripe: { secretKey: stripeSecret },
      };
    } catch (error) {
      console.error('Failed to load secrets from Secrets Manager:', error);
      throw error;
    }
  }

  loadFromEnv() {
    this.secrets = {
      database: {
        url: process.env.DATABASE_URL,
      },
      aws: {
        accessKeyId: process.env.AWS_ACCESS_KEY_ID,
        secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
        region: process.env.AWS_REGION || 'us-east-1',
      },
      stripe: {
        secretKey: process.env.STRIPE_SECRET_KEY,
      },
    };
  }

  validate() {
    const required = {
      production: ['database.url', 'aws.accessKeyId', 'stripe.secretKey'],
      development: [],
    };

    const requiredForEnv = required[process.env.NODE_ENV] || [];

    for (const path of requiredForEnv) {
      const value = path.split('.').reduce((obj, key) => obj?.[key], this.secrets);
      if (!value) {
        throw new Error(`Missing required secret: ${path}`);
      }
    }
  }

  get(path) {
    return path.split('.').reduce((obj, key) => obj?.[key], this.secrets);
  }
}

module.exports = new Config();
```

