### 3. **Implement Key Rotation in app.js**

```javascript
const jwt = require('jsonwebtoken');

// Support for rotating JWT keys
const JWT_KEYS = {
  current: process.env.JWT_SECRET,
  previous: process.env.JWT_SECRET_PREVIOUS // Keep for grace period
};

/**
 * Verify token with key rotation support
 */
function verifyTokenWithRotation(token) {
  const errors = [];

  // Try current key first
  try {
    return jwt.verify(token, JWT_KEYS.current);
  } catch (err) {
    errors.push({ key: 'current', error: err.message });
  }

  // Fall back to previous key for seamless rotation
  if (JWT_KEYS.previous) {
    try {
      const decoded = jwt.verify(token, JWT_KEYS.previous);
      console.warn('Token verified with previous key - consider re-issuing');
